from IQEngine.interface import AbstractFrontendValidator
from IQEngine.const import AssetType, EntrustDirection, FuturesDirection, ExchangeType
from IQEngine.utils import user_log
class PositionValidator(AbstractFrontendValidator):
    def __init__(self, engine):
        self._engine = engine
    def can_submit_order(self, account, order):
        if order.asset.type == AssetType.STOCK.value:
            pass
        elif order.asset.type == AssetType.FUTURE.value:
            position = account.positions[order.symbol]
            if order.futures_direction == FuturesDirection.CLOSE:
                if order.entrust_direction == EntrustDirection.BUY:
                    sell_amount = position.sell_amount
                    if order.amount > sell_amount:
                        user_log.warning('{}的卖单持仓量不足，买平下单失败'.format(order.symbol))
                        return False
                else:
                    buy_amount = position.buy_amount
                    if order.amount > buy_amount:
                        user_log.warning('{}的买单持仓量不足，卖平下单失败'.format(order.symbol))
                        return False
            elif order.futures_direction == FuturesDirection.CLOSE_TODAY:
                if order.asset.exchange != ExchangeType.XSGE.value:
                    user_log.warning('{}不支持平今仓的操作，下单失败'.format(order.symbol))
                    return False
                elif order.entrust_direction == EntrustDirection.BUY:
                    if order.amount > position.sell_today_amount:
                        user_log.warning('{}的卖单持仓量不足，买平下单失败'.format(order.symbol))
                        return False
                    return True
                elif order.amount > position.buy_today_amount:
                    user_log.warning('{}的买单持仓量不足，卖平下单失败'.format(order.symbol))
                    return False
            else:
                return True
        elif not order.asset.type == AssetType.OPTION.value:
            position = account.positions[order.symbol]
            if order.futures_direction == FuturesDirection.CLOSE:
                if order.entrust_direction == EntrustDirection.BUY:
                    sell_amount = position.sell_amount
                    if order.amount > sell_amount:
                        user_log.warning('{}的卖单持仓量不足，买平下单失败'.format(order.symbol))
                        return False
                else:
                    buy_amount = position.buy_amount
                    if order.amount > buy_amount:
                        user_log.warning('{}的买单持仓量不足，卖平下单失败'.format(order.symbol))
                        return False
            else:
                return True
        if order.entrust_direction == EntrustDirection.SELL:
            positions = account.positions[order.symbol]
            can_submit_amount = positions.sellable
            if order.amount > can_submit_amount:
                user_log.warning('{}的持仓量不足，下单失败'.format(order.symbol))
                return False
    def can_cancel_order(self, account, order):
        return True
